$js = @'
const { chromium } = require('@playwright/test');
(async () => {
  const b = await chromium.launch({ channel: 'msedge' });
  const pg = await b.newPage({ viewport:{width:1920,height:1080} });
  await pg.goto('http://127.0.0.1:8081/index.html#/market-monitor', { waitUntil:'domcontentloaded', timeout:60000 }).catch(e=>console.error(e.message));
  await pg.waitForSelector('.mm-dashboard',{timeout:20000}).catch(()=>{});
  await pg.waitForTimeout(2500);
  // Locate the pay legend by label '公积金贷款'
  const info = await pg.evaluate(() => {
    const all = Array.from(document.querySelectorAll('*'));
    const nameCell = all.find(e=>e.children.length===0 && e.textContent.trim()==='公积金贷款');
    if(!nameCell) return {found:false};
    const row = nameCell.parentElement;
    const kids = Array.from(row.children).map(c=>{
      const r=c.getBoundingClientRect();
      return {cls:c.className.slice(0,40), txt:c.textContent.trim().slice(0,10), w:Math.round(r.width), left:Math.round(r.left), right:Math.round(r.right)};
    });
    return {found:true, rowW:Math.round(row.getBoundingClientRect().width), kids};
  });
  console.log(JSON.stringify(info,null,1));
  await pg.screenshot({ path: process.argv[2] }); // full page
  await b.close();
})();
