    // walk up to the donut+legend group, then find donut wrapper & canvas
    const group = label.closest('.flex');
    const card = label.closest('[class*="bg-slate-50"]');
    const canvas = card.querySelector('canvas');
    const cr = canvas ? canvas.getBoundingClientRect() : null;
    // donut wrapper: the div with aspect-square
    const donut = card.querySelector('.aspect-square');
    const dr = donut ? donut.getBoundingClientRect() : null;
    const cardR = card.getBoundingClientRect();
    return {
      found:true,
      canvas: cr?{w:Math.round(cr.width),h:Math.round(cr.height)}:null,
      donut: dr?{w:Math.round(dr.width),h:Math.round(dr.height)}:null,
      card:{w:Math.round(cardR.width),h:Math.round(cardR.height)}
    };
  });
  console.log(JSON.stringify(info));
  await b.close();
})();
